// This test is compiled in an isolated runtime copy. Its adapter include is
// generated by test_thread_crt_native.py with teardown observation only.
#include <cassert>
#include <cstdio>
#include <cstring>
#include <vector>
#include <cstdlib>
// The C header too, before malloc is redefined below: the one of libstdc++
// declares std::malloc again when the adapter includes it first.
#include <stdlib.h>
#include <new>
#define private public
#include "../src/x86_app.h"
#include "fixture_native_modules.h"
#undef private
static void ThreadCrtObserve(X86::Application *, bool);
static unsigned malloc_countdown, malloc_failures;
static void *ThreadCrtMalloc(size_t size)
{
    if(malloc_countdown && !--malloc_countdown) { ++malloc_failures; return nullptr; }
    return std::malloc(size);
}
#define malloc ThreadCrtMalloc
#include "../src/x86_thread_crt_test.inc"
#undef malloc
using U = unsigned;
static U teardown_calls, teardown_blocks;
static U teardown_heap;
static std::vector<U> teardown_pointers;
static void ThreadCrtObserve(X86::Application *app, bool after)
{
    const U error=app->last_error;
    if(!after)
    {
        teardown_pointers.clear();
        teardown_heap=app->crt_heap;
        if(app->crt_threads)
        {
            for(auto *p=app->crt_threads->allocations;p;p=p->next)
            {
                const U args[]={app->crt_heap,0,p->pointer};
                assert(app->HeapApi("HeapSize",args)>=116);
                teardown_pointers.push_back(p->pointer);
            }
            assert(teardown_pointers.size()==app->crt_threads->live_allocations);
        }
        ++teardown_calls;
    }
    else
    {
        assert(!app->crt_threads || !app->crt_threads->live_allocations);
        for(const auto pointer:teardown_pointers)
        {
            const U args[]={teardown_heap,0,pointer};
            assert(!app->HeapApi("HeapSize",args));
            ++teardown_blocks;
        }
        for(const auto &t:app->threads) assert(!t.crt_tls && !t.crt_start_data);
    }
    app->last_error=error;
}
static std::vector<unsigned char> load(const char *path)
{
    FILE *file=fopen(path,"rb"); assert(file);
    fseek(file,0,SEEK_END); const auto size=ftell(file); assert(size>0);
    rewind(file); std::vector<unsigned char> bytes(size);
    assert(fread(bytes.data(),1,bytes.size(),file)==bytes.size()); fclose(file); return bytes;
}
static void main_thread(X86::Application &app)
{
    app.current_thread=0;
    assert(app.cpu->Restore(app.threads[0].context)==X86::CpuError::Ok);
    app.pending=app.threads[0].pending;
    app.waiting=app.threads[0].waiting;
    app.depth=app.threads[0].depth;
    app.last_error=app.threads[0].last_error;
}
static U gate(X86::Application &app,const char *name)
{
    for(U i=0;i<app.import_count;++i)
        if(!strcmp(app.imports[i].name,name)) return 0x70000000+i*16;
    fprintf(stderr,"Missing existing guest import: %s\n",name); assert(false); return 0;
}
static U worker_code(X86::Application &app)
{
    // Own stdcall x86 function. Report is {stage,errno,gate,result,errno_value}.
    // It enters the actual CRT API, optionally waits, then returns normally.
    std::vector<unsigned char> code;
    auto b=[&](U n){code.push_back(n);};
    auto d=[&](U n){for(U i=0;i<4;++i)b(n>>(8*i));};
    b(0x53); b(0x8b);b(0x5c);b(0x24);b(8); // push ebx; mov ebx,[esp+8]
    b(0xb8);d(gate(app,"_errno"));b(0xff);b(0xd0);
    b(0x89);b(0x43);b(4); // report errno pointer
    b(0x8b);b(0x4b);b(16); b(0x89);b(8); // *errno=report.value
    b(0xc7);b(3);d(1); // report.stage=1
    b(0x8b);b(0x43);b(8); b(0x85);b(0xc0); // eax=gate; test eax,eax
    b(0x74);b(10); // no gate skips wait
    b(0x6a);b(0xff);b(0x50); b(0xb8);d(gate(app,"WaitForSingleObject"));b(0xff);b(0xd0);
    b(0xc7);b(3);d(2); b(0x8b);b(0x43);b(12); b(0x5b);b(0xc2);b(4);b(0);
    const U address=0x51000000;
    assert(app.Map(address,4096,7) && app.Store(address,code.data(),code.size()));
    return address;
}
static U begin(X86::Application &app,U function,U report,U flags=0)
{
    main_thread(app);
    const U args[]={0,0,function,report,flags,0};
    return app.CrtThreadApi("_beginthreadex",args);
}
static U report(X86::Application &app,U event,U result,U error)
{
    const U pointer=app.Allocate(20), words[]={0,0,event,result,error};
    assert(pointer && app.Store(pointer,words,sizeof words)); return pointer;
}
static void run_until(X86::Application &app,U address,U value)
{
    for(U i=0;i<1000 && app.Read32(address)!=value;++i)
    {
        app.Pump(8);
        if(app.Status()==X86::Application::Failed)fprintf(stderr,"Native CRT worker: %s\n",app.Error());
        assert(app.Status()!=X86::Application::Failed && app.Status()!=X86::Application::Exited);
    }
    assert(app.Read32(address)==value);
}
static U thread_index(X86::Application &app,U handle)
{
    auto *h=app.FindKernelHandle(handle); assert(h && h->kind==2);return h->object;
}
static void verify_allocations(X86::Application &app,U expected)
{
    assert(app.crt_threads && app.crt_threads->live_allocations==expected);
    U count=0;
    for(auto *p=app.crt_threads->allocations;p;p=p->next)
    {
        const U args[]={app.crt_heap,0,p->pointer};
        assert(app.HeapApi("HeapSize",args)>=116); ++count;
    }
    assert(count==expected);
}
int main(int argc,char **argv)
{
    assert(argc==3);const auto exe=load(argv[1]),font=load(argv[2]);
    for(U profile=0;profile<7;++profile)
    {
        auto *app=new X86::Application(nullptr);
        assert(FixtureModules::KeepNative(*app));
        if(profile>=5) malloc_countdown=profile==5 ? 1 : 2;
        const bool started=app->Start(exe.data(),exe.size(),font.data(),font.size(),"COMMON.EXE");
        if(profile>=5)
        {
            assert(!started && app->Status()==X86::Application::Failed && !malloc_countdown);
            if(profile==5) assert(!app->crt_threads);
            else assert(app->crt_threads && !app->crt_threads->live_allocations);
            delete app;
            continue;
        }
        if(!started)fprintf(stderr,"CRT startup: %s\n",app->Error());
        assert(started && app->crt_threads);
        // The existing COMMON image supplies import gates; its main fixture is
        // deliberately never executed by this isolated native test.
        app->threads[0].suspended=1;
        main_thread(*app);
        const U main_errno=app->CrtErrno();
        // PTD+0 holds the owning thread's identity. Identities are global and
        // never recycled, so later profiles do not start again at one.
        assert(main_errno && app->Read32(main_errno-8)==app->threads[0].id);
        app->Write32(main_errno,77);
        verify_allocations(*app,1);
        const U function=worker_code(*app);
        if(profile<2)
        {
            U slots[80];
            for(U i=0;i<80;++i)
            {
                slots[i]=app->TlsApi("TlsAlloc",nullptr);assert(slots[i]==i);
                const U args[]={slots[i],0x98760000+i};assert(app->TlsApi("TlsSetValue",args));
            }
            assert(app->TlsApi("TlsAlloc",nullptr)==~0u);
            const U event_args[]={0,1,0,0};
            const U event=app->ThreadApi("CreateEventA",event_args);assert(event);
            const U suspended=report(*app,0,0x12345678,101);
            const U blocked=report(*app,event,0x98765432,102);
            const U finished=report(*app,0,0xabcdef01,103);
            const U sh=begin(*app,function,suspended,4),bh=begin(*app,function,blocked),fh=begin(*app,function,finished);
            assert(sh && bh && fh);
            const U si=thread_index(*app,sh),bi=thread_index(*app,bh),fi=thread_index(*app,fh);
            verify_allocations(*app,4);
            if(profile==1)
            {
                const U a[]={sh},b[]={bh},c[]={fh};
                assert(app->ThreadApi("CloseHandle",a) && app->ThreadApi("CloseHandle",b) && app->ThreadApi("CloseHandle",c));
            }
            run_until(*app,blocked,1);run_until(*app,finished,2);
            // The worker has returned to native RunEx and ended before its
            // fiber yields to the host after the final guest stage write.
            assert(app->threads[fi].done && app->threads[fi].result==0xabcdef01);
            assert(!app->threads[fi].crt_tls && !app->threads[fi].crt_start_data);
            assert(app->threads[si].suspended && app->threads[si].crt_start_data && !app->Read32(suspended));
            assert(app->threads[bi].block==2 && app->threads[bi].crt_tls);
            verify_allocations(*app,3);
            main_thread(*app);
            assert(app->CrtErrno()==main_errno && app->Read32(main_errno)==77);
            assert(app->Read32(app->Read32(blocked+4))==102);
            for(U i=0;i<80;++i)
            {
                const U args[]={slots[i]};
                assert(app->TlsApi("TlsGetValue",args)==0x98760000+i && app->TlsApi("TlsFree",args));
            }
            // Destructor must release main+blocked+suspended PTDs while its
            // existing heap still exists. The isolated observer checks this.
        }
        else if(profile==2)
        {
            // Force the existing heap backend to reject the PTD allocation.
            // This injects a provider failure, not new production behavior.
            const U heap=app->crt_heap;
            app->crt_heap=0x12345678;
            app->last_error=0x9988;
            app->threads[0].last_error=0x9988;
            const U r=report(*app,0,7,7);
            assert(!begin(*app,function,r));
            assert(app->last_error==0x9988 && app->Read32(main_errno)==77);
            assert(app->Status()!=X86::Application::Failed && app->LiveThreads()==1);
            app->crt_heap=heap;
            verify_allocations(*app,1);
            const U successful=begin(*app,function,r);assert(successful);
            run_until(*app,r,2);verify_allocations(*app,1);
        }
        else if(profile==3)
        {
            // An invalid private TLS token reaches the actual provider's
            // failure path. The original GetData must stop with Fatal16;
            // its partially allocated PTD remains owned until teardown.
            const U slot=app->crt_threads->core.tls_index;
            app->crt_threads->core.tls_index=0x1234;
            assert(!app->CrtErrno() && app->Status()==X86::Application::Failed);
            app->crt_threads->core.tls_index=slot;
            verify_allocations(*app,2);
        }
        else
        {
            // Refuse only the adapter's Allocation bookkeeping node. The
            // real original heap, current PTD, errno and scheduler survive.
            const U r=report(*app,0,19,19);
            app->last_error=app->threads[0].last_error=0x7766;
            malloc_countdown=1;
            assert(!begin(*app,function,r) && !malloc_countdown);
            assert(app->last_error==0x7766 && app->Read32(main_errno)==77);
            assert(app->LiveThreads()==1 && app->Status()!=X86::Application::Failed);
            verify_allocations(*app,1);
            assert(begin(*app,function,r));run_until(*app,r,2);
            verify_allocations(*app,1);
        }
        const U observed_before=teardown_calls;
        delete app;
        assert(teardown_calls==observed_before+1);
    }
    assert(teardown_calls==7 && teardown_blocks>=10 && malloc_failures==3);
    puts("THREAD CRT NATIVE PASS: seven lifecycle/failure profiles, 80 public TLS slots, fallible state/bookkeeping allocation, real PTD heaps and observed destructor cleanup");
}
